async function run() {
  const wb = new ExcelJS.Workbook();
  wb.creator = "MHC Test Automation";
  wb.created = new Date();

  // ── Summary Sheet ──
  const ws = wb.addWorksheet("Summary");
  ws.columns = [
    { header:"Module", key:"m", width:30 },
    { header:"Total", key:"t", width:10 },
    { header:"Critical", key:"cr", width:12 },
    { header:"High", key:"hi", width:10 },
    { header:"Medium", key:"me", width:12 },
    { header:"Low", key:"lo", width:10 },
  ];
  ws.getRow(1).height = 28;
  ws.getRow(1).eachCell(c => {
    c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FF1F3864"} };
    c.font = { bold:true, color:{argb:"FFFFFFFF"}, size:11 };
    c.alignment = { horizontal:"center", vertical:"middle" };
    c.border = { top:{style:"thin"}, bottom:{style:"thin"}, left:{style:"thin"}, right:{style:"thin"} };
  });

  const map = {};
  for (const r of tc) {
    const [no,mod,,,,type,pri] = r;
    if (!map[mod]) map[mod] = { t:0, Critical:0, High:0, Medium:0, Low:0 };
    map[mod].t++;
    map[mod][pri] = (map[mod][pri]||0)+1;
  }

  let tT=0,tC=0,tH=0,tM=0,tL=0;
  for (const [mod, s] of Object.entries(map)) {
    const row = ws.addRow([mod, s.t, s.Critical||0, s.High||0, s.Medium||0, s.Low||0]);
    row.eachCell(c => {
      c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FFF7FBFF"} };
      c.alignment = { horizontal:"center", vertical:"middle" };
      c.border = { top:{style:"thin",color:{argb:"FFD0D0D0"}}, bottom:{style:"thin",color:{argb:"FFD0D0D0"}}, left:{style:"thin",color:{argb:"FFD0D0D0"}}, right:{style:"thin",color:{argb:"FFD0D0D0"}} };
    });
    row.getCell(1).alignment = { horizontal:"left", vertical:"middle", indent:1 };
    tT+=s.t; tC+=(s.Critical||0); tH+=(s.High||0); tM+=(s.Medium||0); tL+=(s.Low||0);
  }
  const tr = ws.addRow(["TOTAL", tT, tC, tH, tM, tL]);
  tr.eachCell(c => {
    c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FF1F3864"} };
    c.font = { bold:true, color:{argb:"FFFFFFFF"} };
    c.alignment = { horizontal:"center", vertical:"middle" };
    c.border = { top:{style:"medium"}, bottom:{style:"medium"}, left:{style:"thin"}, right:{style:"thin"} };
  });

  // ── All Test Cases Sheet ──
  const as = wb.addWorksheet("Test Cases", { views:[{ state:"frozen", ySplit:1 }] });
  as.columns = [
    { header:"No", key:"no", width:6 },
    { header:"Module", key:"module", width:22 },
    { header:"Spec File", key:"specFile", width:30 },
    { header:"Test ID", key:"testId", width:16 },
    { header:"Test Name", key:"testName", width:48 },
    { header:"Type", key:"type", width:16 },
    { header:"Priority", key:"priority", width:12 },
    { header:"Precondition", key:"precondition", width:35 },
    { header:"Steps", key:"steps", width:55 },
    { header:"Expected Result", key:"expected", width:55 },
    { header:"Tags", key:"tags", width:38 },
    { header:"Status", key:"status", width:14 },
    { header:"Notes", key:"notes", width:25 },
  ];
  as.getRow(1).height = 30;
  as.getRow(1).eachCell(c => {
    c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FF1F3864"} };
    c.font = { bold:true, color:{argb:"FFFFFFFF"}, size:11 };
    c.alignment = { horizontal:"center", vertical:"middle", wrapText:true };
    c.border = { top:{style:"medium"}, bottom:{style:"medium"}, left:{style:"thin"}, right:{style:"thin"} };
  });

  for (const r of tc) {
    const [no,mod,spec,tid,tname,type,pri,precond,steps,expected,tags] = r;
    const runResult = LAST_RUN_STATUS[tid];
    const row = as.addRow({ no, module:mod, specFile:spec, testId:tid, testName:tname, type, priority:pri, precondition:precond, steps, expected, tags, status: runResult ? runResult.status : "", notes: runResult ? runResult.notes : "" });
    row.height = Math.max(40, (steps.split("\n").length) * 15);
    row.eachCell(c => {
      c.alignment = { vertical:"top", wrapText:true };
      c.border = { top:{style:"thin",color:{argb:"FFD0D0D0"}}, bottom:{style:"thin",color:{argb:"FFD0D0D0"}}, left:{style:"thin",color:{argb:"FFD0D0D0"}}, right:{style:"thin",color:{argb:"FFD0D0D0"}} };
      c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FFFFFFFF"} };
    });
    if (runResult) {
      row.getCell(12).fill = { type:"pattern", pattern:"solid", fgColor:{argb: STATUS_COLOR[runResult.status] || "FFF2F2F2"} };
      row.getCell(12).font = { bold:true };
    }
    row.getCell(7).fill = { type:"pattern", pattern:"solid", fgColor:{argb: P[pri]||"FFFFFFFF"} };
    row.getCell(7).font = { bold:true };
    row.getCell(7).alignment = { horizontal:"center", vertical:"top" };
    row.getCell(6).fill = { type:"pattern", pattern:"solid", fgColor:{argb: T[type]||"FFFFFFFF"} };
    row.getCell(6).alignment = { horizontal:"center", vertical:"top" };
    row.getCell(1).alignment = { horizontal:"center", vertical:"top" };
    row.getCell(4).alignment = { horizontal:"center", vertical:"top", wrapText:true };
    if (!runResult) row.getCell(12).fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FFF2F2F2"} };
    row.getCell(12).alignment = { horizontal:"center", vertical:"top" };
  }
  as.autoFilter = { from:{row:1,column:1}, to:{row:tc.length+1,column:13} };

  // ── Per-Module Sheets ──
  const modules = [...new Set(tc.map(r=>r[1]))];
  for (const mod of modules) {
    const mcs = tc.filter(r=>r[1]===mod);
    const sn = mod.slice(0,31).replace(/[/\\?*[\]]/g,"-");
    const ms = wb.addWorksheet(sn);
    ms.columns = [
      { header:"No", key:"no", width:6 },
      { header:"Test ID", key:"testId", width:16 },
      { header:"Test Name", key:"testName", width:45 },
      { header:"Type", key:"type", width:15 },
      { header:"Priority", key:"priority", width:12 },
      { header:"Precondition", key:"precond", width:35 },
      { header:"Steps", key:"steps", width:55 },
      { header:"Expected Result", key:"expected", width:50 },
      { header:"Status", key:"status", width:14 },
      { header:"Notes", key:"notes", width:25 },
    ];
    ms.getRow(1).height = 28;
    ms.getRow(1).eachCell(c => {
      c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FF2E75B6"} };
      c.font = { bold:true, color:{argb:"FFFFFFFF"}, size:11 };
      c.alignment = { horizontal:"center", vertical:"middle", wrapText:true };
      c.border = { top:{style:"medium"}, bottom:{style:"medium"}, left:{style:"thin"}, right:{style:"thin"} };
    });
    let ri = 1;
    for (const r of mcs) {
      const [no,modn,spec,tid,tname,type,pri,precond,steps,expected,tags] = r;
      ri++;
      const runResult = LAST_RUN_STATUS[tid];
      const row = ms.addRow({ no:ri-1, testId:tid, testName:tname, type, priority:pri, precond, steps, expected, status: runResult ? runResult.status : "", notes: runResult ? runResult.notes : "" });
      row.height = Math.max(40, steps.split("\n").length * 15);
      row.eachCell(c => {
        c.alignment = { vertical:"top", wrapText:true };
        c.border = { top:{style:"thin",color:{argb:"FFD0D0D0"}}, bottom:{style:"thin",color:{argb:"FFD0D0D0"}}, left:{style:"thin",color:{argb:"FFD0D0D0"}}, right:{style:"thin",color:{argb:"FFD0D0D0"}} };
        c.fill = { type:"pattern", pattern:"solid", fgColor:{argb: ri%2===0?"FFF7FBFF":"FFFFFFFF"} };
      });
      row.getCell(4).fill = { type:"pattern", pattern:"solid", fgColor:{argb: T[type]||"FFFFFFFF"} };
      row.getCell(5).fill = { type:"pattern", pattern:"solid", fgColor:{argb: P[pri]||"FFFFFFFF"} };
      row.getCell(5).font = { bold:true };
      row.getCell(5).alignment = { horizontal:"center", vertical:"top" };
      row.getCell(4).alignment = { horizontal:"center", vertical:"top" };
      row.getCell(1).alignment = { horizontal:"center", vertical:"top" };
      row.getCell(2).alignment = { horizontal:"center", vertical:"top", wrapText:true };
      if (runResult) {
        row.getCell(9).fill = { type:"pattern", pattern:"solid", fgColor:{argb: STATUS_COLOR[runResult.status] || "FFF2F2F2"} };
        row.getCell(9).font = { bold:true };
      } else {
        row.getCell(9).fill = { type:"pattern", pattern:"solid", fgColor:{argb:"FFF2F2F2"} };
      }
      row.getCell(9).alignment = { horizontal:"center", vertical:"top" };
    }
    ms.autoFilter = { from:{row:1,column:1}, to:{row:mcs.length+1,column:10} };
  }

  const out = path.join(__dirname, "MHC-UAT-TestCases.xlsx");
  await wb.xlsx.writeFile(out);
  console.log("OK: " + out);
  console.log("Total TC: " + tc.length);
}

run().catch(e => { console.error(e.message); process.exit(1); });
